INSERT INTO `atividades` (`id`, `pergunta`, `id_materia`) VALUES
(1, 'Qual é o valor de f(3) na função f(x) = 2x + 5?', 1),
(2, 'Em uma progressão aritmética de primeiro termo 3 e razão 4, qual é o 10º termo?', 1),
(3, 'Sendo A = {1, 2, 3, 4} e B = {3, 4, 5, 6}, quantos elementos tem o conjunto A ∩ B?', 1),
(4, 'Um produto que custava R$ 80,00 recebeu um desconto de 25%. Qual é o novo preço?', 1),
(5, 'Quais são as raízes da equação x² − 5x + 6 = 0?', 1),
(6, 'Qual figura de linguagem aparece em “Seus olhos são duas estrelas”?', 2),
(7, 'Qual é a classe gramatical da palavra destacada em: “Os alunos estudaram MUITO para a prova”?', 2),
(8, 'Qual característica é típica do Barroco?', 2),
(9, 'Qual gênero textual tem como finalidade relatar fatos reais e recentes de interesse público?', 2),
(10, 'Em qual das frases a concordância verbal está correta?', 2),
(11, 'Em qual cidade-Estado da Grécia Antiga surgiu a democracia?', 3),
(12, 'Qual era a base da economia na Europa feudal?', 3),
(13, 'Qual movimento cultural, nascido na Itália entre os séculos XIV e XVI, valorizou o humanismo e o antropocentrismo?', 3),
(14, 'Quem iniciou a Reforma Protestante, em 1517, ao divulgar as 95 teses?', 3),
(15, 'Qual foi o sistema de colonização adotado pelos portugueses no Brasil em 1534, dividindo o território em grandes faixas de terra?', 3),
(16, 'O número atômico (Z) de um elemento indica a quantidade de:', 4),
(17, 'Qual é o tipo de ligação química entre o sódio (Na) e o cloro (Cl) no sal de cozinha (NaCl)?', 4),
(18, 'Qual modelo atômico propôs um núcleo pequeno, denso e positivo, com os elétrons girando ao redor?', 4),
(19, 'Qual das opções representa uma substância simples?', 4),
(20, 'Elementos químicos que ficam na mesma coluna (grupo) da tabela periódica têm em comum:', 4),
(21, 'Qual organela celular é responsável pela respiração celular e pela produção da maior parte do ATP?', 5),
(22, 'Qual organela das células vegetais realiza a fotossíntese?', 5),
(23, 'Qual molécula armazena a informação genética dos seres vivos?', 5),
(24, 'Em qual fase da mitose os cromossomos se alinham no plano equatorial da célula?', 5),
(25, 'Como se chama a passagem de água através de uma membrana semipermeável, do meio menos concentrado para o mais concentrado?', 5),
(26, 'Um carro percorre 150 km em 2 horas. Qual é a sua velocidade média?', 6),
(27, 'Qual é a unidade de medida de força no Sistema Internacional?', 6),
(28, 'Qual lei física explica por que os passageiros são lançados para a frente quando o ônibus freia bruscamente?', 6),
(29, 'Um corpo parte do repouso com aceleração constante de 3 m/s². Qual é a sua velocidade após 4 s?', 6),
(30, 'Desprezando a resistência do ar e adotando g = 10 m/s², qual é a altura de queda de um objeto que cai do repouso durante 3 s?', 6),
(31, 'Qual linha imaginária divide a Terra nos hemisférios Norte e Sul?', 7),
(32, 'Quando é meio-dia (12h) em Greenwich, que horas são em Brasília (fuso UTC−3)?', 7),
(33, 'Em um mapa com escala 1:100.000, 1 cm no papel corresponde a quanto na realidade?', 7),
(34, 'Em qual camada da Terra estão as placas tectônicas?', 7),
